<template>
  <div class="">
    <backHomeBtn />

    <svgIcon class="svgClass" @click="showPop" icon-class="浙政钉"></svgIcon>

    <div class="svgChoose">
      <el-popover
        placement="bottom-start"
        width="460"
        trigger="click"
        @show="$refs['iconSelect'].reset()"
      >
        <iconSelect ref="iconSelect" @selected="selected" />
        <el-input
          slot="reference"
          v-model="formData.icon"
          clearable
          placeholder="点击选择图标"
          readonly
        >
          <svg-icon
            v-if="formData.icon"
            slot="prefix"
            :icon-class="formData.icon"
            class="el-input__icon"
            style="height: 32px; width: 16px"
          />
          <i v-else slot="prefix" class="iconfont if-sousuo el-input__icon" />
        </el-input>
      </el-popover>
    </div>

    <div class="svgChoose">
      <el-input v-model="formData.iconName" readonly placeholder="">
        <template slot="append">
          <div class="choose-class" @click="showIconDialog">
            <i class="iconfont if-sousuo" /> <span>选择</span>
          </div>
        </template>
      </el-input>
    </div>

    <iconDialog ref="iconDialog" @on-response="getIcon" />
  </div>
</template>

<script>
import svgIcon from "@/components/SvgIcon/index.vue";
import iconSelect from "@/components/IconSelect/index.vue";
import iconDialog from "@/components/chooseIconDialog/iconDialog.vue";

export default {
  components: { svgIcon, iconSelect, iconDialog },
  data() {
    return {
      icon: "微信",
      formData: {
        icon: "",
        iconName: "",
      },
    };
  },
  methods: {
    showPop() {
      this.$message.success("aaa");
    },

    selected(name) {
      this.formData.icon = name;
    },

    showIconDialog() {
      const passData = {
        data: this.formData.icon,
        title: "选择图标",
      };
      this.$refs.iconDialog.showDialog(passData);
    },

    getIcon(data) {
      this.$set(this.formData, "iconName", data.font_class);
      this.$forceUpdate();
    },
  },
  mounted() {},
  beforeDestroy() {},
};
</script>

<style lang="scss" scoped>
.svgClass {
  width: 90px;
  height: 90px;
  cursor: pointer;
  margin-left: 10px;
}

.svgChoose {
}
</style>
