<!--
 * @Description: 选择icon的弹窗 使用请看 typeDialog  页面
 * @Author: mhf
 * @Date: 2023-07-27 17:02:15
-->
<template>
  <el-dialog
    v-dialog-out
    width="800px"
    append-to-body
    :title="title"
    :visible.sync="dialogVisible"
    :before-close="hideDialog"
    :close-on-click-modal="false"
  >
    <div class="dialog-body">
      <div
        v-for="(item, index) in iconfontArr"
        :key="index"
        :class="checkIndex === index ? 'check-class icon-box' : 'icon-box'"
        @click="checkIcon(item, index)"
      >
        <i :class="['iconfont', 'if-' + item.font_class]" />
        <span> {{ item.name }} </span>
      </div>
    </div>

    <div class="dialog-footer">
      <el-button @click="hideDialog">取 消</el-button>
      <el-button type="primary" @click="submitDialog">确 定</el-button>
    </div>
  </el-dialog>
</template>

<script>
export default {
  name: "IconDialog",
  components: {},
  props: {},
  dicts: [],
  data() {
    return {
      dialogVisible: false,
      title: "",
      iconfontArr: require("@/assets/icons/iconfont/iconfont.json").glyphs,
      checkIndex: null,
      checkItem: {}, // 回显选中项 {font_class: '', icon_id: ''}
    };
  },
  created() {},
  mounted() {},
  methods: {
    showDialog(data) {
      this.dialogVisible = true;
      this.title = data.title;
      if (data.data) {
        this.checkItem = JSON.parse(data.data);
        this.iconfontArr.forEach((item, index) => {
          if (item.icon_id === this.checkItem.icon_id) {
            this.checkIndex = index;
          }
        });
      }
    },

    hideDialog() {
      this.dialogVisible = false;
      this.checkIndex = null;
      this.checkItem = {};
    },

    submitDialog() {
      this.$emit("on-response", this.checkItem); // 将选中的数据传给父组件
      this.hideDialog();
    },

    checkIcon(item, index) {
      this.checkIndex = index;
      this.checkItem = {
        icon_id: item.icon_id,
        font_class: item.font_class,
      };
    },
  },
};
</script>

